import * as THREE from 'three';
import {endpointPlan,bufferSource} from './endpoint-plan.js';

export function createRouting({scene,parts,camera,escape,onSelect,onFrame}){
 const group=new THREE.Group();scene.add(group);
 let data=null,selected=null,active=null,layer='all',enabled=true,pins=[];
 let plan=null,destination=null,hoverPins=[];
 const viewport=document.querySelector('#viewport'),tags=document.createElement('div');tags.className='endpoint-tags';viewport.append(tags);
 // Exposed socket receptacles sit inward of the SMT tails. Picking offset only;
 // copper and endpoint positions retain the original PCB pad coordinates.
 const contactZ=p=>p.ref==='J21'?p.z+Math.sign(-6.250305-p.z)*1.05:p.z;
 function pinPosition(p){const part=parts.get(p.ref);const shift=part?part.position.y-part.userData.base.y:0;return new THREE.Vector3(p.x,(p.layer===32?-.43:.43)+shift,p.z);}
 function updateLabels(){const w=viewport.clientWidth,h=viewport.clientHeight;for(const el of tags.children){const v=pinPosition(el.pin).project(camera);el.hidden=v.z>1||v.z< -1;el.style.left=Math.max(4,Math.min(w-170,(v.x+1)*w/2+12))+'px';el.style.top=Math.max(35,Math.min(h-55,(1-v.y)*h/2+(el.dataset.kind==='START'?16:-46)))+'px';}}
 function rebuildHover(){hoverPins=[];if(!data)return;for(const [ref,part] of parts){if(!/^J/.test(ref)||!part.visible)continue;const box=new THREE.Box3().setFromObject(part),side=part.userData.side==='bottom'?-1:1;for(const p of data.components[ref]||[]){if(!p.number)continue;hoverPins.push({pin:p,point:new THREE.Vector3(p.x,side>0?box.max.y+.05:box.min.y-.05,contactZ(p)),side});}}}
 function drawEndpoints(){tags.replaceChildren();if(!plan)return;const list=[['START',plan.start],...(destination?[['END',destination]]:[])];for(const [kind,p] of list){const pos=pinPosition(p);dot(pos.x,pos.y,pos.z,.3,kind==='START'?0x23ffd0:0xffbe54);const ring=new THREE.Mesh(new THREE.RingGeometry(.38,.48,32).rotateX(-Math.PI/2),new THREE.MeshBasicMaterial({color:kind==='START'?0x23ffd0:0xffbe54,depthTest:false,side:THREE.DoubleSide}));ring.position.copy(pos);ring.renderOrder=25;group.add(ring);if(kind==='END'&&parts.has(p.ref)){const outline=new THREE.Box3Helper(new THREE.Box3().setFromObject(parts.get(p.ref)),0xffbe54);outline.material.depthTest=false;outline.renderOrder=19;group.add(outline);}const el=document.createElement('div');el.className='endpoint-tag';el.dataset.kind=kind;el.pin=p;el.innerHTML=`<b>${kind}</b> ${escape(p.ref)} · ${p.ref==='U1'?'SoC ball':'pin'} ${escape(p.number)}<small>${escape(netName(p))}</small>`;tags.append(el);}updateLabels();}
 function endpointPanel(){if(!plan)return '';return `<section class="endpoint-summary"><h3>PIN TO PIN</h3><b>Start: ${escape(plan.start.ref)} pin ${escape(plan.start.number)} · ${escape(netName(plan.start))}</b>${destination?`<p class="endpoint-result">End: ${escape(destination.ref)} ${destination.ref==='U1'?'SoC ball':'pin'} ${escape(destination.number)}<br>${escape(netName(destination))}</p>`:'<p>No other pad is assigned to this net in the PCB export.</p>'}${plan.stages.map(s=>`<p>Via ${escape(s.description)}: pin ${s.from.number} ↔ pin ${s.to.number}. This is a buffer stage, not continuous copper. <a href="${bufferSource}" target="_blank" rel="noreferrer">Datasheet ↗</a></p>`).join('')}${plan.shared?'<p>Shared power/ground net: many endpoints, no single destination. Plane fills are omitted.</p>':''}<button id="frame-endpoints">Show both endpoints</button><label class="pin-filter">Destination / branch<select id="endpoint-destination">${plan.ends.map((p,i)=>`<option value="${i}" ${p===destination?'selected':''}>${escape(p.ref)} ${p.ref==='U1'?'ball':'pin'} ${escape(p.number)} · ${escape(netName(p))}</option>`).join('')}</select></label><p>${plan.ends.length} connected pads. Pin numbers identify package pads/balls; the signal name is the PCB net, not a software GPIO number.</p></section>`;}
 const palette=[0x00a782,0xe8a52c,0x568dff,0xd774ed,0xf47763,0x5dc4d2,0xb1bb4d,0xbb85ff];
 const layerName=l=>l===1?'L1 · Top':l===32?'L8 · Bottom':`L${l} · Inner`;
 const netName=p=>p.net===null?'No net':data.nets[p.net].name;
 const signal=p=>selected==='J6'?({'1':'GND','2':'RX','3':'TX'}[p.number]||netName(p)):netName(p);
 function clear(){for(const c of [...group.children]){c.dispose?.();c.geometry?.dispose();c.material?.map?.dispose();c.material?.dispose();group.remove(c);}pins=[];}
 function dot(x,y,z,r,color,pin){const m=new THREE.Mesh(new THREE.SphereGeometry(r,8,6),new THREE.MeshBasicMaterial({color,depthTest:false}));m.position.set(x,y,z);m.renderOrder=22;if(pin){m.userData.pin=pin;pins.push(m);}group.add(m);}
 function label(text,x,y,z){const c=document.createElement('canvas');c.width=512;c.height=64;const ctx=c.getContext('2d');ctx.fillStyle='#10242bef';ctx.fillRect(0,0,512,64);ctx.fillStyle='#e9fff7';ctx.font='27px Arial';ctx.fillText(text,12,43);const t=new THREE.CanvasTexture(c);t.colorSpace=THREE.SRGBColorSpace;const s=new THREE.Sprite(new THREE.SpriteMaterial({map:t,depthTest:false}));s.position.set(x,y,z);s.scale.set(6,.75,1);s.renderOrder=24;group.add(s);}
 function draw(){clear();rebuildHover();tags.replaceChildren();if(!data||!selected)return;
  const part=parts.get(selected),side=part?.userData.side==='bottom'?-1:1;
  // Pin markers follow the selected package when exploded; copper stays on the PCB.
  const bounds=part?new THREE.Box3().setFromObject(part):null;
  const y=bounds?(side>0?bounds.max.y+.13:bounds.min.y-.13):side*.43;
  const cp=(data.components[selected]||[]).filter(p=>p.number);
  if(/^J/.test(selected))for(const p of cp){dot(p.x,y,contactZ(p),selected==='J6'?.22:.13,p.net===active?0xffcf5c:0x21bf99,p);if(cp.length<=4)label(`${p.number} · ${signal(p)}`,p.x+3.8,y,p.z);}
  drawEndpoints();if(!enabled||active===null)return;const ns=plan?.nets||[data.nets[active]],n={tracks:ns.flatMap(n=>n.tracks),pads:ns.flatMap(n=>n.pads),vias:ns.flatMap(n=>n.vias)};
  // Exact exported centerlines, laid on their copper layer; depth bypass is an explicit X-ray overlay.
  const yFor=l=>.386334-(l===32?7:l-1)*.110381;
  for(const l of data.layers){if(layer!=='all'&&Number(layer)!==l)continue;const vertices=[];
   for(const [tl,x1,z1,x2,z2,w] of n.tracks){if(tl!==l)continue;const dx=x2-x1,dz=z2-z1,len=Math.hypot(dx,dz);if(!len)continue;const h=Math.max(w,.045)/2,ox=-dz/len*h,oz=dx/len*h,y=yFor(l);vertices.push(x1+ox,y,z1+oz,x1-ox,y,z1-oz,x2+ox,y,z2+oz,x2+ox,y,z2+oz,x1-ox,y,z1-oz,x2-ox,y,z2-oz);}
   if(vertices.length){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(vertices,3));const m=new THREE.Mesh(g,new THREE.MeshBasicMaterial({color:palette[data.layers.indexOf(l)],side:THREE.DoubleSide,depthTest:false}));m.renderOrder=20;group.add(m);}
  }
  const pads=n.pads.filter(p=>layer==='all'||p.layer===74||p.layer===Number(layer));
  const dots=new THREE.InstancedMesh(new THREE.SphereGeometry(.10,8,6),new THREE.MeshBasicMaterial({color:0xffd574,depthTest:false}),pads.length),matrix=new THREE.Matrix4();
  pads.forEach((p,i)=>dots.setMatrixAt(i,matrix.makeTranslation(p.x,p.layer===32?-.41:.41,p.z)));dots.renderOrder=21;group.add(dots);
  const vias=n.vias.filter(v=>layer==='all'||(Number(layer)>=v[3]&&Number(layer)<=v[4]));
  const rings=new THREE.InstancedMesh(new THREE.RingGeometry(.5,1,12).rotateX(-Math.PI/2),new THREE.MeshBasicMaterial({color:0xffffff,side:THREE.DoubleSide,depthTest:false}),vias.length);
  vias.forEach(([x,z,d],i)=>{const r=Math.max(.07,d*.5);matrix.makeScale(r,1,r);matrix.setPosition(x,.42,z);rings.setMatrixAt(i,matrix);});rings.renderOrder=21;group.add(rings);
 }
 function choose(p){if(selected!==p.ref)onSelect?.(p.ref);selected=p.ref;active=p.net;layer='all';plan=endpointPlan(data,p);destination=plan.ends[0]||null;draw();renderPanel();onFrame?.(p,destination);}
 function renderPanel(){const host=document.querySelector('#pin-panel');if(!host)return;if(!data){host.innerHTML='<p class="muted">Loading PCB pin map…</p>';return;}if(plan)host.parentElement.prepend(host);else host.parentElement.append(host);const cp=(data.components[selected]||[]).filter(p=>p.number),n=active===null?null:data.nets[active];
  host.innerHTML=`${endpointPanel()}<div class="connections-title">PINS & PCB ROUTING <span>${cp.length}</span></div><p class="muted">Select a pin to follow its copper traces. Pin names are board-side signals.</p>${selected==='J6'?'<p class="serial-note"><b>J6 serial console</b> · 1 GND · 2 RX · 3 TX<br>Adapter TX → board RX; adapter RX → board TX.</p>':''}<label class="pin-filter">Find pin or signal<input id="pin-search" type="search" placeholder="Pin number, RX, GND…"></label><div class="pin-list">${cp.map((p,i)=>`<button class="pin-button ${active!==null&&p.net===active?'active':''}" data-pin="${i}"><b>${escape(p.number||'Pad')}</b><span>${escape(signal(p))}</span></button>`).join('')||'<p class="muted">No matching pads in this PCB export.</p>'}</div><label class="pin-filter">Copper layer<select id="copper-layer"><option value="all">All layers · X-ray</option>${data.layers.map(l=>`<option value="${l}" ${String(l)===layer?'selected':''}>${layerName(l)}</option>`).join('')}</select></label>${n?`<div class="trace-info"><b>${escape(n.name)}</b><p>${n.tracks.filter(t=>layer==='all'||t[0]===Number(layer)).length} trace segments · ${n.vias.length} vias · ${n.pads.length} pads</p><div class="layer-legend">${data.layers.filter(l=>n.tracks.some(t=>t[0]===l)&&(layer==='all'||Number(layer)===l)).map(l=>`<span><i style="background:#${palette[data.layers.indexOf(l)].toString(16).padStart(6,'0')}"></i>${layerName(l)}</span>`).join('')}</div><button id="clear-trace">Clear trace</button></div>`:'<p class="muted">No signal selected.</p>'}<p class="muted">X-ray highlights follow the exported PCB coordinates, visible through packages. Copper pours and plane fills are not shown; GND and power connections may continue through those planes. Small differences from the CAD revision are possible.</p>`;
  const frame=host.querySelector('#frame-endpoints');if(frame)frame.onclick=()=>onFrame?.(plan.start,destination);const dest=host.querySelector('#endpoint-destination');if(dest)dest.onchange=e=>{destination=plan.ends[Number(e.target.value)];draw();renderPanel();onFrame?.(plan.start,destination);};host.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>choose(cp[Number(b.dataset.pin)]));host.querySelector('#pin-search').oninput=e=>{const q=e.target.value.toLowerCase();const frame=host.querySelector('#frame-endpoints');if(frame)frame.onclick=()=>onFrame?.(plan.start,destination);const dest=host.querySelector('#endpoint-destination');if(dest)dest.onchange=e=>{destination=plan.ends[Number(e.target.value)];draw();renderPanel();onFrame?.(plan.start,destination);};host.querySelectorAll('[data-pin]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q));};host.querySelector('#copper-layer').onchange=e=>{layer=e.target.value;draw();renderPanel();};const c=host.querySelector('#clear-trace');if(c)c.onclick=()=>{active=null;plan=null;destination=null;draw();renderPanel();};
 }
 fetch(new URL('./assets/routing.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('PCB map unavailable');return r.json();}).then(d=>{data=d;document.querySelector('#viewport').dataset.routingReady='true';draw();renderPanel();}).catch(()=>{const h=document.querySelector('#pin-panel');if(h)h.textContent='PCB pin map could not load. Reload to retry.';});
 return {select(ref){selected=ref;active=null;plan=null;destination=null;draw();},draw,renderPanel,updateLabels,setEnabled(value){enabled=value;draw();},hit(ray){if(!hoverPins.length)rebuildHover();let best=null,score=Infinity;for(const h of hoverPins){if(h.side*camera.position.y<0)continue;const distance=ray.ray.distanceSqToPoint(h.point);const radius=h.pin.ref==='J21'?.36:.26;if(distance<radius*radius&&distance<score){best=h.pin;score=distance;}}return best;},choose,describe:p=>`${p.ref} pin ${p.number} · ${netName(p)}`};
}
